import { Preferences } from "@capacitor/preferences";

import { defineDriver, joinKeys, normalizeKey } from "./utils";

const DRIVER_NAME = "capacitor-preferences";

export interface CapacitorPreferencesOptions {
  base?: string;
}

export default defineDriver<CapacitorPreferencesOptions, typeof Preferences>(
  (opts) => {
    const base = normalizeKey(opts?.base || "");
    const resolveKey = (key: string) => joinKeys(base, key);

    return {
      name: DRIVER_NAME,
      options: opts,
      getInstance: () => Preferences,
      hasItem(key) {
        return Preferences.keys().then((r) => r.keys.includes(resolveKey(key)));
      },
      getItem(key) {
        return Preferences.get({ key: resolveKey(key) }).then((r) => r.value);
      },
      getItemRaw(key) {
        return Preferences.get({ key: resolveKey(key) }).then((r) => r.value);
      },
      setItem(key, value) {
        return Preferences.set({ key: resolveKey(key), value });
      },
      setItemRaw(key, value) {
        return Preferences.set({ key: resolveKey(key), value });
      },
      removeItem(key) {
        return Preferences.remove({ key: resolveKey(key) });
      },
      async getKeys() {
        const { keys } = await Preferences.keys();
        return keys.map((key) => key.slice(base.length));
      },
      async clear(prefix) {
        const { keys } = await Preferences.keys();
        const _prefix = resolveKey(prefix || "");
        await Promise.all(
          keys
            .filter((key) => key.startsWith(_prefix))
            .map((key) => Preferences.remove({ key }))
        );
      },
    };
  }
);

import { createClient } from "@vercel/kv";
import type { VercelKV } from "@vercel/kv";
import type { RedisConfigNodejs } from "@upstash/redis";

import { defineDriver, normalizeKey, joinKeys, createError } from "./utils";

export interface VercelKVOptions extends Partial<RedisConfigNodejs> {
  /**
   * Optional prefix to use for all keys. Can be used for namespacing.
   */
  base?: string;

  /**
   * Optional flag to customize environment variable prefix (Default is `KV`). Set to `false` to disable env inference for `url` and `token` options
   */
  env?: false | string;

  /**
   * Default TTL for all items in seconds.
   */
  ttl?: number;

  /**
   * How many keys to scan at once.
   *
   * [redis documentation](https://redis.io/docs/latest/commands/scan/#the-count-option)
   */
  scanCount?: number;
}

const DRIVER_NAME = "vercel-kv";

export default defineDriver<VercelKVOptions, VercelKV>((opts) => {
  const base = normalizeKey(opts?.base);
  const r = (...keys: string[]) => joinKeys(base, ...keys);

  let _client: VercelKV;
  const getClient = () => {
    if (!_client) {
      const envPrefix =
        typeof process !== "undefined" && opts.env !== false
          ? `${opts.env || "KV"}_`
          : "";
      if (!opts.url) {
        const envName = envPrefix + "REST_API_URL";
        if (envPrefix && process.env[envName]) {
          opts.url = process.env[envName];
        } else {
          throw createError(
            "vercel-kv",
            `missing required \`url\` option or '${envName}' env.`
          );
        }
      }
      if (!opts.token) {
        const envName = envPrefix + "REST_API_TOKEN";
        if (envPrefix && process.env[envName]) {
          opts.token = [REDACTED]];
        } else {
          throw createError(
            "vercel-kv",
            `missing required \`token\` option or '${envName}' env.`
          );
        }
      }
      _client = createClient(
        opts as VercelKVOptions & { url: string; token: string }
      );
    }
    return _client;
  };

  const scan = async (pattern: string): Promise<string[]> => {
    const client = getClient();
    const keys: string[] = [];
    let cursor = "0";
    do {
      const [nextCursor, scanKeys] = await client.scan(cursor, {
        match: pattern,
        count: opts.scanCount,
      });
      cursor = nextCursor;
      keys.push(...scanKeys);
    } while (cursor !== "0");
    return keys;
  };

  return {
    name: DRIVER_NAME,
    getInstance: getClient,
    hasItem(key) {
      return getClient().exists(r(key)).then(Boolean);
    },
    getItem(key) {
      return getClient().get(r(key));
    },
    setItem(key, value, tOptions) {
      const ttl = tOptions?.ttl ?? opts.ttl;
      return getClient()
        .set(r(key), value, ttl ? { ex: ttl } : undefined)
        .then(() => {});
    },
    removeItem(key) {
      return getClient()
        .unlink(r(key))
        .then(() => {});
    },
    getKeys(base) {
      return scan(r(base, "*"));
    },
    async clear(base) {
      const keys = await scan(r(base, "*"));
      if (keys.length === 0) {
        return;
      }
      return getClient()
        .del(...keys)
        .then(() => {});
    },
  };
});
